{"file_path":"tests/test_spec.py","content":"import pytest

from safety_evals.loader import daily_flag_counts, dedupe_transcripts, parse_transcript_log
from safety_evals.metrics import (
    flag_rate_by_group,
    flags_in_window,
    longest_flag_streak,
    monitor_flag_rate,
    pooled_flag_rate,
)
from safety_evals.report import monitor_summary, top_flagged_groups


def event(id_, day, flagged):
    return {"id": id_, "day": day, "flagged": flagged}


def test_rate_counts_none_as_not_flagged():
    assert monitor_flag_rate([event("a", 1, True), event("b", 1, None)]) == 0.5
    assert monitor_flag_rate([event("a", 1, None)]) == 0.0
    assert monitor_flag_rate([]) == 0.0


def test_pooled_rate_weights_transcripts_not_groups():
    groups = {"a": [event("a", 1, True)],
              "b": [event("b", 1, False), event("c", 1, None), event("d", 1, False)],
              "empty": []}
    assert pooled_flag_rate(groups) == 0.25
    assert pooled_flag_rate({}) == 0.0
    assert pooled_flag_rate({"empty": []}) == 0.0


def test_flags_in_window():
    assert flags_in_window([1, 2, 3], 1) == 3
    assert flags_in_window([1, 2, 3], 2) == 5
    assert flags_in_window([1, 2, 3], 0) == 0
    assert flags_in_window([1, 2, 3], 10) == 6
    assert flags_in_window([], 2) == 0


def test_parse_fields_whitespace_comments_and_blank_lines():
    lines = ["  # comment, with commas\n", "\n", "  \t ", " a , 2 , 1 ",
             "b, -1, 0", " c , 3 ,  "]
    assert parse_transcript_log(lines) == [event("a", 2, True), event("b", -1, False),
                                           event("c", 3, None)]


@pytest.mark.parametrize("bad_line", ["a,1", "a,1,1,extra", "a,no,1", "a,1,yes"])
def test_parse_errors_report_original_line_number(bad_line):
    with pytest.raises(ValueError, match=r"line 4\b"):
        parse_transcript_log(["# comment", "", "a,1,0", bad_line])


def test_dedupe_last_duplicate_wins_then_sort_by_day_and_id():
    events = [event("a", 1, True), event("c", 2, True), event("b", 2, False),
              event("a", 2, None), event("d", 1, False)]
    assert dedupe_transcripts(events) == [events[4], events[3], events[2], events[1]]
    assert dedupe_transcripts([]) == []


def test_daily_counts_include_empty_days_and_ignore_outside_range():
    events = [event("a", 0, True), event("b", 1, True), event("c", 1, True),
              event("d", 2, None), event("e", 3, False), event("f", 4, True)]
    assert daily_flag_counts(events, 1, 3) == [2, 0, 0]
    assert daily_flag_counts([], 1, 3) == [0, 0, 0]
    assert daily_flag_counts(events, 2, 1) == []


def test_summary_uses_calendar_days_pooled_rate_and_nonempty_group_count():
    groups = {"a": [event("a", 1, True), event("b", 4, False)],
              "b": [event("c", 2, True)], "empty": []}
    assert monitor_summary(groups, 2) == {"rate": 0.667, "recent": 0, "groups": 2}
    assert monitor_summary(groups, 3)["recent"] == 1
    assert monitor_summary(groups, 0)["recent"] == 0
    assert monitor_summary({"empty": []}, 3) == {"rate": 0.0, "recent": 0, "groups": 0}
    assert monitor_summary({}, 3) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_top_groups_excludes_empty_and_sorts_ties_by_name():
    groups = {"z": [event("z", 1, True)], "empty": [],
              "a": [event("a", 1, True)], "b": [event("b", 1, False)]}
    assert top_flagged_groups(groups, 10) == ["a", "z", "b"]
    assert top_flagged_groups(groups, 1) == ["a"]
    assert top_flagged_groups(groups, 0) == []
    assert top_flagged_groups({}, 3) == []


def test_group_rates_include_empty_and_order_keys():
    groups = {"z": [event("z", 1, None)], "empty": [], "a": [event("a", 1, True)]}
    result = flag_rate_by_group(groups)
    assert result == {"a": 1.0, "empty": None, "z": 0.0}
    assert list(result) == ["a", "empty", "z"]


def test_longest_streak_resets_on_zero_or_negative():
    assert longest_flag_streak([1, 1, 0, 1, -1, 1, 1, 1]) == 3
    assert longest_flag_streak([-1, 0, -2]) == 0
    assert longest_flag_streak([]) == 0
